<script>
const sheet = {
    set: (id, formula) => {
        document.getElementById(id).value = formula;
        recalculate();
    },
    get: (id) => {
        const element = document.getElementById(id);
        if (element.type === 'text') {
            return element.value;
        } else {
            // For other input types, return the raw value as a string.
            return element.rawValue;
        }
    },
    raw: (id) => {
        const element = document.getElementById(id);
        return element.rawValue;
    }
};

function recalculate() {
    const cells = document.querySelectorAll('input[type="text"]');
    for (let i = 0; i < cells.length; i++) {
        const cell = cells[i];
        const formula = sheet.get(cell.id);
        if (formula && formula.startsWith("=")) {
            try {
                // Evaluate the formula using a safe evaluation approach
                const result = eval(formula.substring(1)); // Remove '=' sign

                // Handle circular references
                let cycleDetected = false;
                const visitedCells = new Set();

                function checkCycle(cellId) {
                    if (visitedCells.has(cellId)) {
                        cycleDetected = true;
                        return true;
                    }
                    visitedCells.add(cellId);

                    let rawValue = sheet.raw(cellId);
                    if (!rawValue || rawValue === "#CYCLE") {
                        return false;
                    }

                    const formulaText = sheet.get(cellId);
                    if (formulaText && formulaText.startsWith("=")) {
                        for(let j=0; j<cells.length; ++j){
                            if (cells[j].id === cellId) continue; //skip the current cell
                           if(checkCycle(cells[j].id)) return true;
                        }

                    }
                   return false;
                }
                 // Check for cycles before updating.
               if (checkCycle("A1")) {
                  for (let k=0; k<cells.length; ++k){
                     cells[k].value = "#CYCLE";
                  }
                  return;
               }

                sheet.set(cell.id, result);
            } catch (error) {
                // Handle errors like invalid formulas or references.
                sheet.set(cell.id, '#ERR');
            }
        } else {
            // If not a formula, display the raw value.
           let value = sheet.get(cell.id);

             if (isNaN(parseFloat(value)) && !isFinite(value)) {
               sheet.set(cell.id, value);
           }
        }
    }
}

// Initial calculation
recalculate();

document.getElementById('export').addEventListener('click', () => {
    const csvData = [];
    const cells = document.querySelectorAll('input[type="text"]');
